"use client"
import React, { useState } from 'react'
import { login } from '../../../lib/api'

export default function LoginPage() {
  const [phoneOrEmail, setPhoneOrEmail] = useState('')
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault()
    setLoading(true)
    setError(null)
    try {
      await login({ identifier: phoneOrEmail })
      // redirect to dashboard
      window.location.href = '/dashboard'
    } catch (err: any) {
      setError(err?.message || 'Login failed')
    } finally { setLoading(false) }
  }

  return (
    <div className="max-w-md mx-auto mt-12">
      <h1 className="text-2xl font-semibold mb-4">Sign in</h1>
      <form onSubmit={handleSubmit} className="space-y-3">
        <input value={phoneOrEmail} onChange={e=>setPhoneOrEmail(e.target.value)} placeholder="Phone or email" className="w-full p-3 border rounded" />
        <button disabled={loading} className="w-full bg-blue-600 text-white p-3 rounded">{loading ? 'Sending...' : 'Send OTP / Login'}</button>
        {error && <div className="text-red-600">{error}</div>}
      </form>
    </div>
  )
}
